args.sql:
DROP VIEW IF EXISTS esi_view;
CREATE VIEW esi_view AS
SELECT 
    se.zoneref,
    ROUND(
        (100.0 - 2.5 * ABS(se.ambictemp - 20) - POWER(ABS((se.humepct - 50.0) / 2.0), 1.5) - 600.0 / (se.illumelux + 100))::numeric, 2
    ) AS esi_score
FROM scanenvironment se;
